import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse(`{"title":"Points d'accès","description":"","frontmatter":{},"headers":[],"relativePath":"fr/concepts/endpoints.md","filePath":"fr/concepts/endpoints.md","lastUpdated":1784903584000}`),o={name:"fr/concepts/endpoints.md"};function i(c,e,d,r,p,l){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="points-d-acces" tabindex="-1">Points d&#39;accès <a class="header-anchor" href="#points-d-acces" aria-label="Permalink to &quot;Points d&#39;accès&quot;">​</a></h1><p>Un point d&#39;accès est une méthode HTTP + chemin spécifique qui peut être invoquée (par exemple, <code>GET /api/users/{id}</code>). Les points d&#39;accès sont les opérations API réelles que le LLM découvre, inspecte et appelle.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>Chaque point d&#39;accès contient :</p><ul><li><strong>Méthode HTTP</strong> : GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS</li><li><strong>Chemin</strong> : <code>/api/v1/users/{id}</code></li><li><strong>Résumé</strong> : une courte description de ce que fait le point d&#39;accès — très utile pour que le LLM comprenne son objectif en un coup d&#39;œil</li><li><strong>Description</strong> : une explication détaillée du comportement, des paramètres et des cas d&#39;utilisation du point d&#39;accès</li><li><strong>Paramètres</strong> : chemin, requête, en-tête, cookie</li><li><strong>Corps de la requête</strong> : pour POST/PUT/PATCH</li><li><strong>Réponses</strong> : codes d&#39;état et schémas de réponse</li></ul><p>Les champs <code>summary</code> et <code>description</code> proviennent du fichier OpenAPI/Swagger/Postman. Ils sont le principal moyen pour le LLM de comprendre ce que fait un point d&#39;accès. Des résumés bien rédigés rendent la découverte des points d&#39;accès beaucoup plus efficace.</p><h2 id="outils-mcp-pour-les-points-d-acces" tabindex="-1">Outils MCP pour les points d&#39;accès <a class="header-anchor" href="#outils-mcp-pour-les-points-d-acces" aria-label="Permalink to &quot;Outils MCP pour les points d&#39;accès&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outil</th><th>Description</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>Tous les points d&#39;accès dans une spec</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Points d&#39;accès dans une collection</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Points d&#39;accès dans une étiquette</td></tr><tr><td><code>endpoint_by_id</code></td><td>Résumé rapide d&#39;un point d&#39;accès</td></tr><tr><td><code>inspect</code></td><td>Détails complets du point d&#39;accès (schémas, paramètres)</td></tr><tr><td><code>invoke</code></td><td>Appeler le point d&#39;accès</td></tr><tr><td><code>search</code></td><td>Rechercher des points d&#39;accès par texte</td></tr></tbody></table><h2 id="points-d-acces-deprecies" tabindex="-1">Points d&#39;accès dépréciés <a class="header-anchor" href="#points-d-acces-deprecies" aria-label="Permalink to &quot;Points d&#39;accès dépréciés&quot;">​</a></h2><p>Les points d&#39;accès marqués comme <code>deprecated</code> dans la spec sont affichés avec un avis lors de l&#39;inspection.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Les points d&#39;accès sont <strong>en lecture seule</strong> du point de vue de swag2mcp. Il n&#39;y a pas de paramètres de configuration YAML pour les points d&#39;accès — vous ne pouvez pas ajouter, supprimer, renommer ou modifier des points d&#39;accès dans <code>swag2mcp.yaml</code>.</p><p>Pour modifier les points d&#39;accès (en ajouter de nouveaux, mettre à jour les résumés, modifier les paramètres, marquer comme dépréciés), modifiez le fichier OpenAPI/Swagger/Postman original et exécutez <code>swag2mcp update</code> pour ré-analyser et ré-indexer.</p><h2 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Requête : &quot;Afficher les détails pour GET /animal/{animalId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ Résultat :</span></span>
<span class="line"><span>  GET /animal/{animalId}</span></span>
<span class="line"><span>  Résumé : Trouver un animal par ID</span></span>
<span class="line"><span>  Description : Retourne un seul animal par son ID</span></span>
<span class="line"><span>  Paramètres :</span></span>
<span class="line"><span>    - animalId (chemin, entier, requis)</span></span>
<span class="line"><span>  Réponses :</span></span>
<span class="line"><span>    - 200 : Objet Animal</span></span>
<span class="line"><span>    - 400 : Erreur</span></span>
<span class="line"><span>    - 404 : Non trouvé</span></span></code></pre></div>`,15)])])}const h=s(o,[["render",i]]);export{m as __pageData,h as default};
